#!/usr/bin/env bash
# il_sel97_box.sh: ON xbox1, start the il_old selection-half ADD-ON: one interleaved run3 + sim2 launch of 95 cells
# (descriptive; NOT a registered IL launch or replacement; it cannot amend the registered IL result). The sequence is
# ilc_box.sh's (freeze, settings equality, guards, confirmed start); only names, pins and the cell check differ.
# GENERATED by make_sel97_addon.py (v2: --box-only); do not edit by hand.
#   bash ~/phase2/il_stage/il_sel97_box.sh sel97 <base URLs, comma-separated> <branch commit>
set -euo pipefail
trap '' PIPE  # a closed stdout (ssh gone) must not kill the wrapper: writes fail with EPIPE instead, and are ignored
H=$1 BASES=$2 COMMIT=$3
PY=/home/aswin/sims/simulated-control-evals-sept/.venv/bin/python; TREE=/home/aswin/phase2/sims-sept-strict-off/src
IMAGES=/home/aswin/phase2/attack_check_strict/results/devbox_setup_2026-10-08_163146/images.json; ST=/home/aswin/phase2/il_stage
HF=$H
[[ $H == sel97 ]] || { echo "host $H: this script runs only the sel97 add-on"; exit 2; }
BOXL=xbox1; ORIG=/home/aswin/phase2/runs/2026-10-14_il_old; PREVS="/home/aswin/phase2/runs/2026-10-14_il_old /home/aswin/phase2/runs/2026-10-15_il_old_rlr /home/aswin/phase2/runs/2026-10-15_il_old_rlr3 /home/aswin/phase2/runs/2026-10-15_simh_q4 /home/aswin/phase2/runs/2026-10-15_simh_q2"  # v2: + sim-honest Q2
SIMH_PINS="pilot_simh_q4.yaml:942f88b0c1c34d9ae8d83b9658727e1ec93f5c0674b0b32105b37b306cdade87 pilot_simh_q2.yaml:dace5410a1c408159eebcdf2b126ff3c22e7b18415c26c3f2de3f17795d9513e"  # v2: staged sim-honest configs, exact names
KIND=311; MAIN=/home/aswin/phase2/il_refindex_old; MANIFEST=/home/aswin/phase2/attack_check_311/config/harness_manifest_fu.tsv; CAP=2044; TSHA=d21e9b32fa21ca2984ee3c0061437dbcf9da5c56c5f90dfc3ffe62f1b6f0ebff; CSHA=3970c0ee88a116d4e5d179741f7a2c88d9e7d44a8727cb772b2691f3384c1e16; ILTASKS=config/tasks_il_old_all.json; ILTSHA=69c709d91da2f8952c0a3f4ceddf3e05cac5044f73a596eb253bb5763f70ee4e; RSHA=79acbfc1ef4523f9a57cc19dc876252159c6c1d62521001f1ac71e2644036940; OSHA=cf53b22603ae738fa7666aac3f1e708d913cee957112c23eb62c13aa6a30d4a7; CAPSTOP_SHA=6689a761a6a5d879310dcb6c7e0e10eea8840dd4eb88fd44b9b3403222ba1ccb; GATE_SHA=624e35e33f393146978a65b63050fbc8de8a8726a9135137c72f67d68a6cc795  # on xbox1
[[ $KIND == 311 ]] || { echo "completion launches are +311-harness launches only"; exit 2; }
SRC=/home/aswin/phase2/attack_check_311; SOCK=phase2; GSOCK=guards; CHECKS=$ST/checks
RUN=/home/aswin/phase2/runs/2026-10-15_il_sel97_addon; GATEPAUSE=gate_pause_311_rl.py; CAPSTOP=$((CAP + 100)); APPR=/home/aswin/phase2/approaches
PYP="PYTHONPATH=$TREE "  # as il311_box.sh / fu_launch.sh
SESSION=ilsel97; LOG=/home/aswin/phase2/il_sel97_addon.log; TMP=$(mktemp -d)
LAUNCH_CMD="cd $SRC && PATH=$SRC/fixed_digest_lookup:\$PATH IMAGES_JSON=$IMAGES ${PYP}RR_OWNER_ID=aswin-surya rr-env run --env-file config/env.aws.tpl -- $PY $SRC/run_pilot.py --pilot-config config/pilot_il_sel97.yaml --base-urls $BASES --commit $COMMIT --approaches $APPR --references-from $MAIN --out $RUN > $RUN.launcher.log 2>&1"
log() {  # never fails: a logging error must not change control flow
  local line; line="$(TZ=America/Los_Angeles date '+%F %T PT' 2>/dev/null) [il sel97 @ $BOXL] $*"
  echo "$line" 2>/dev/null || true; echo "$line" >> "$LOG" 2>/dev/null || true
}
fail() { log "IL GATE FAIL: $*"; exit 1; }
sessions() {  # the session names on a tmux socket; no server = none; any other tmux error returns 1 (callers fail)
  local out rc=0; out=$(tmux -L "$1" ls -F '#S' 2>&1) || rc=$?
  # no server = none: "no server running", or (a socket never created on this box) exactly this one message
  if (( rc == 0 )); then printf '%s\n' "$out"
  elif [[ $out == *"no server running"* || $out == "error connecting to /tmp/tmux-$UID/$1 (No such file or directory)" ]]; then :
  else echo "tmux -L $1: $out" >&2; return 1; fi
}
has_session() {  # 0 = live, 1 = absent; a tmux or grep error exits the script through fail
  local list rc=0; list=$(sessions "$1") || fail "cannot list tmux -L $1 sessions"
  in_list "$list" "$2"
}
no_launcher() {  # fails unless NO run_pilot.py process runs on the box (pgrep's own status checked; it excludes itself)
  local live rc=0; live=$(pgrep -af 'run_pilot\.py') || rc=$?
  (( rc == 0 || rc == 1 )) || fail "pgrep failed ($rc)"
  (( rc == 1 )) && [[ -z $live ]] || fail "another launcher is running: $(grep -o -- '--out [^ ]*' <<< "$live" | sort -u | tr '\n' ' ')"
}
in_list() {  # 0 if line $2 is in the newline-separated list $1 (pure bash: no redirection or process that could fail)
  [[ $'\n'"$1"$'\n' == *$'\n'"$2"$'\n'* ]]
}
absent() {  # fails unless nothing exists at path $1 (a symlink counts, even dangling) and its parent is inspectable
  [[ -d ${1%/*} && -r ${1%/*} && -x ${1%/*} ]] || fail "cannot inspect ${1%/*}"
  [[ ! -e $1 && ! -L $1 ]] || fail "$1 exists"
}
sha_ok() {  # $1 file, $2 expected sha256
  local h; h=$(sha256sum < "$1") || fail "sha256sum $1"; [[ ${h:0:64} == "$2" ]] || fail "$1: sha256 ${h:0:16}... != expected ${2:0:16}..."
}
[[ $BASES =~ ^https://[^,]+(,https://[^,]+){5}$ ]] || fail "expected 6 base URLs"
absent "$RUN"
absent "$SRC/results/PAUSE_SIMS"
! has_session $SOCK "$SESSION" || fail "session $SESSION is live"
# (a) every earlier launch on this box has finished (the original IL launch, relayed when placed, and the box's own)
for p in $PREVS; do
  "$PY" -c "import json,sys; sys.exit(0 if json.load(open(sys.argv[1])).get('finished') else 1)" "$p/launch.json" \
    || fail "$p has not finished (or its launch.json can't be read)"
done
log "earlier launches finished: $PREVS"
# (a2) v2: EVERY launch on this box has finished. Run dirs are enumerated (nullglob), each must be inspectable; a dir with
# no launch.json (neither file nor symlink) never got a launcher far (no_launcher covers one starting); any other
# launch.json must be a readable regular file reporting finished (Codex r39: a dangling symlink or unreadable dir fails)
[[ -d /home/aswin/phase2 && -r /home/aswin/phase2 && -x /home/aswin/phase2 ]] || fail "cannot inspect /home/aswin/phase2"
for q in /home/aswin/phase2/runs /home/aswin/phase2/nm /home/aswin/phase2/nm/runs; do  # in order: each parent proven inspectable first (Codex r39b)
  [[ ( ! -e $q && ! -L $q ) || ( -d $q && -r $q && -x $q ) ]] || fail "cannot inspect $q"
done
[[ -d /home/aswin/phase2/runs ]] || fail "no /home/aswin/phase2/runs"
shopt -s nullglob; RDIRS=(/home/aswin/phase2/runs/*/ /home/aswin/phase2/nm/runs/*/); shopt -u nullglob
for d in "${RDIRS[@]}"; do
  [[ -r $d && -x $d ]] || fail "cannot inspect $d"
  l=${d}launch.json
  [[ -e $l || -L $l ]] || continue
  [[ -f $l && -r $l ]] || fail "$l is not a readable regular file"
  "$PY" -c "import json,sys; sys.exit(0 if json.load(open(sys.argv[1])).get('finished') else 1)" "$l" \
    || fail "${d%/} has not finished (or its launch.json can't be read)"
done
log "every launch.json under runs/ and nm/runs/ reports finished (${#RDIRS[@]} run dirs inspected)"
sha_ok "$MAIN/launch.json" "$RSHA"  # the main (references) pinned; relayed when placed
sha_ok "$ORIG/launch.json" "$OSHA"  # il_old, as read at selection
sha_ok "$CHECKS/sim_cap_stop.py" "$CAPSTOP_SHA"
sha_ok "$CHECKS/$GATEPAUSE" "$GATE_SHA"
# (b) one launcher per settings dir: no run_pilot.py process at all on the box
no_launcher
log "no other run_pilot.py on the box"
# 1. the harness is still frozen (the staged il and ilrr files are excluded by name)
(cd "$SRC" && set -o pipefail && find . -type f ! -path './results/*' ! -path '*/__pycache__/*' ! -path './attempt/results/*' \
  ! -path './config/harness_manifest*.tsv' ! -path './config/pilot_il_*' ! -path './config/tasks_il_*' \
  ! -path './config/pilot_ilrr_*' ! -path './config/tasks_ilrr_*' ! -path './config/ilrr_*' \
  ! -path './config/pilot_ilc_*' ! -path './config/tasks_ilc_*' ! -path './config/ilc_*' \
  ! -path './config/pilot_ilrr2_*' ! -path './config/pilot_ilrr3_*' ! -path './config/tasks_ilrr3_*' ! -path './config/ilrr3_*' \
  ! -path './config/pilot_simh_q4.yaml' ! -path './config/pilot_simh_q2.yaml' -print0 \
  | LC_ALL=C sort -z | xargs -0 sha256sum > "$TMP/now.tsv") || fail "hashing the harness failed"
grep -v '  ./config/harness_manifest' "$MANIFEST" > "$TMP/frozen.tsv" || fail "reading $MANIFEST failed"
[[ -s $TMP/now.tsv && -s $TMP/frozen.tsv ]] || fail "empty hash list"
cmp -s "$TMP/now.tsv" "$TMP/frozen.tsv" || fail "$SRC differs from $MANIFEST"
for pin in $SIMH_PINS; do  # v2: each excluded sim-honest config is absent or at its pinned sha256
  f=$SRC/config/${pin%%:*}; [[ ! -e $f && ! -L $f ]] || sha_ok "$f" "${pin##*:}"
done
log "freeze: $SRC matches $MANIFEST ($(wc -l < "$TMP/now.tsv") files; sim-honest configs absent or pinned: $SIMH_PINS)"
# 2. this completion's files
cp "$ST/pilot_il_sel97.yaml" "$ST/tasks_il_sel97.json" "$SRC/config/"
sha_ok "$SRC/config/tasks_il_sel97.json" "$TSHA"
sha_ok "$SRC/config/pilot_il_sel97.yaml" "$CSHA"
sha_ok "$SRC/$ILTASKS" "$ILTSHA"
# 3. the cells: distinct verbatim original entries of il_old's IL task file, both of whose arms were 'not run' with 0 attempts in il_old
(cd "$SRC" && "$PY" - "$ILTASKS" "$ORIG" <<'PY') || fail "config or task file"
import json, sys
from pathlib import Path
import yaml
iltasks, orig = sys.argv[1], sys.argv[2]
cfg = yaml.safe_load(open("config/pilot_il_sel97.yaml"))
assert cfg["real_arms"] == ["attack"] and cfg["sim_arms"] == ["sim_attack"] and cfg["simulators"] == ["september"], cfg
assert cfg["tasks"] == "config/tasks_il_sel97.json" and cfg["spend"]["cap_usd"] == cfg["spend"]["worst_case_limit_usd"]
cells = json.load(open(cfg["tasks"]))["cells"]
canon = lambda c: json.dumps(c, sort_keys=True)
orig_cells = json.load(open(iltasks))["cells"]
assert cells and set(map(canon, cells)) <= set(map(canon, orig_cells)) and len({c["key"] for c in cells}) == len(cells), "not distinct original entries"
lj = json.load(open(Path(orig) / "launch.json"))
assert lj.get("finished"), "il_old has not finished"
runs = lj["runs"]; runs = list(runs.values()) if isinstance(runs, dict) else runs
by_key = {r["key"]: r for r in runs}
for c in cells:
    for arm in ("attack", "sim_attack@september"):
        r = by_key[f"{arm}/{c['key']}"]
        assert r["state"] == "not run" and not r.get("attempts"), (c["key"], arm, r["state"])
print(f"add-on: {len(cells)} selection-half cells, both arms never started in il_old, all original entries; cap {cfg['spend']['cap_usd']}")
PY
# 4. settings equality (as fu_launch.sh)
GS="results/gate_settings_il_sel97_$(date +%s).json"
(cd "$SRC" && "$PY" gate_settings.py --reference-json config/sim_settings_reference_2026-10-14_125923.json --out "$GS" \
  --harness . > "$GS.log" 2>&1) || fail "settings gate exit"
"$PY" -c "import json,sys; sys.exit(0 if json.load(open(sys.argv[1]))['pass'] else 1)" "$SRC/$GS" || fail "settings gate"
log "settings equality PASS"
printf '{"launch": "il_sel97_addon", "interleaved_launch": true, "addon_of": "%s", "status": "descriptive add-on; not a registered IL launch or replacement; cannot amend the registered IL result", "worlds": {"attack": "run3", "sim_attack@september": "sim2"}, "references_from": "%s", "settings_dir": "/home/aswin/phase2/settings", "harness": "%s", "sim_attempt_timeout_s": 300, "cap_usd": %s, "gate": "gate_pause_311_rl.py %s", "commit": "%s"}\n' \
  "$ORIG" "$MAIN" "$KIND" "$CAP" "$GATE_SHA" "$COMMIT" > "$RUN.il_meta.json"
# 5. the launcher, then the two reviewed guards (pause only); both alive 30 s later, or the launcher is interrupted and
# its exit CONFIRMED. From the launch on, errexit is off and every failure goes through abort().
OURS="--out $RUN( |\$)"  # this launch's processes (pgrep/grep -E): the exact run dir, not a prefix of another
gone() {  # 0 = confirmed gone; 1 = still there; 2 = could not tell (an inspection error is never read as gone)
  local list rc=0; list=$(sessions $SOCK) || return 2
  if in_list "$list" "$SESSION"; then return 1; fi
  pgrep -f -- "$OURS" > /dev/null || rc=$?
  case $rc in 0) return 1 ;; 1) return 0 ;; *) return 2 ;; esac
}
abort() {  # interrupt the launcher and CONFIRM it ended; escalate to kill-session; never report success unconfirmed
  log "ABORT: $1"
  local i j
  for i in 1 2; do
    tmux -L $SOCK send-keys -t "=$SESSION:" C-c > /dev/null 2>&1 || true
    for j in $(seq 30); do gone; if [[ $? == 0 ]]; then log "launcher ended after Ctrl+C"; exit 1; fi; sleep 2; done
  done
  tmux -L $SOCK kill-session -t "=$SESSION" > /dev/null 2>&1 || true
  for j in $(seq 15); do gone; if [[ $? == 0 ]]; then log "launcher session killed"; exit 1; fi; sleep 2; done
  log "LAUNCHER NOT CONFIRMED STOPPED after abort: $SESSION, $RUN (stop it by hand)"; exit 3
}
no_launcher
tmux -L $SOCK new -d -s "$SESSION" "$LAUNCH_CMD" \
  || fail "tmux new (launcher)"
set +e
log "launcher session $SESSION created"
tmux -L $GSOCK new -d -s "sc$SESSION" "$PY $CHECKS/sim_cap_stop.py $RUN $SESSION $CAPSTOP" || abort "tmux new (sim_cap_stop) failed"
tmux -L $GSOCK new -d -s "gp$SESSION" "$PY $CHECKS/$GATEPAUSE $RUN $SESSION" || abort "tmux new ($GATEPAUSE) failed"
log "guards started: sc$SESSION (sim_cap_stop $CAPSTOP), gp$SESSION ($GATEPAUSE) on tmux -L $GSOCK"
sleep 30
list=$(sessions $SOCK) || abort "cannot list tmux -L $SOCK sessions"
in_list "$list" "$SESSION" || abort "the launcher session is gone (see $RUN.launcher.log)"
pgrep -f "sim_cap_stop.py $RUN $SESSION" > /dev/null || abort "sim_cap_stop is not running (or pgrep failed)"
pgrep -f "$GATEPAUSE $RUN $SESSION" > /dev/null || abort "$GATEPAUSE is not running (or pgrep failed)"
rc=0; all=$(pgrep -af 'run_pilot\.py') || rc=$?
[[ $rc == 0 ]] || abort "pgrep finds no launcher process at all (rc $rc)"
others=""; ours=0
while IFS= read -r line; do  # pure bash over pgrep's lines: ours match the exact run dir, anything else is another launcher
  if [[ $line =~ --out\ $RUN(\ |$) ]]; then ours=$((ours + 1)); elif [[ -n $line ]]; then others+="$line"$'\n'; fi
done <<< "$all"
(( ours > 0 )) || abort "no process of this launch found"
[[ -z $others ]] || abort "another launcher is running: ${others:0:300}"
log "STARTED: $SESSION, run $RUN, cap $CAP, guards alive, no other launcher"
